  U.org = () => { const S = S0(); const o = S.db.orgs[0]; return ph(T('Organization', '组织'), T('Information about the organization you belong to.', '你所在组织的信息。')) + card(S.orgName || o.name, U.fact([[T('Description', '描述'), E(o.desc || '—')], [T('Created', '创建时间'), H.fmt(Date.UTC(2026, 5, 3, 2, 0))], [T('Members', '成员'), S.db.members.length], [T('Clusters', '集群'), S.db.clusters.length], [T('Your role', '你的角色'), U.roleName(S.role)]]), U.btn('drawer', T('Edit', '编辑'), { cls: 'sm', icon: 'edit', d: { type: 'editOrg' } })); };
