  U.orgs = () => ph(T('Organizations', '组织'), T('Platform administrators manage organizations but cannot open another organization’s clusters, storage or tasks.', '平台管理员可管理组织，但不能进入其他组织的集群、存储和任务。'), U.btn('drawer', T('New organization', '新建组织'), { cls: 'pri', icon: 'plus', d: { type: 'newOrg' } })) + `<div class="card">${table([[T('Organization', '组织')], [T('Status', '状态')], [T('Members', '成员')], [T('Clusters', '集群')], [T('Protected apps', '受保护应用')]], S0().db.orgs.map((o) => `<tr><td><b>${E(o.name)}</b>${o.sys ? ` <span class="tag">${T('SYSTEM DEFAULT', '系统默认')}</span>` : ''}<div class="t3" style="font-size:11.5px">${E(o.desc)}</div></td><td>${o.st === 'active' ? U.chip('ok', T('Active', '正常')) : U.chip('neutral', T('Disabled', '已停用'))}</td><td class="data">${o.members}</td><td class="data">${o.clusters}</td><td class="data">${o.apps}</td></tr>`))}</div>`;
